import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextLine()) {
            return;
        }
        String line = scanner.nextLine();
        String[] parts = line.split(" ");
        long n = Long.parseLong(parts[0]);
        long k = Long.parseLong(parts[1]);
        System.out.println(getCandiesEaten(n, k));
    }

    static long getCandiesEaten(long n, long k) {
        if (n == 1) return 0;
        n--;
        long candies = 1;
        long sum = 2;
        long consumed = 0;
        while (n > 0) {
            while (candies <= k) {
                candies += sum;
                sum++;
                n--;
            }
            long candiesToSubtract = candies - k;
            n -= candiesToSubtract;
            consumed += candiesToSubtract;
            candies -= candiesToSubtract;
        }
        return consumed;
    }
}

